/**
 * Lightweight Bootstrap 5 UI Controller (Modal & Interactive Triggers)
 * DinePOS Web Application
 */
(function() {
  'use strict';

  window.bootstrap = window.bootstrap || {};

  class Modal {
    constructor(element) {
      this.element = typeof element === 'string' ? document.querySelector(element) : element;
    }

    show() {
      if (!this.element) return;
      this.element.classList.add('show');
      this.element.style.display = 'flex';
      document.body.style.overflow = 'hidden';
    }

    hide() {
      if (!this.element) return;
      this.element.classList.remove('show');
      this.element.style.display = 'none';
      document.body.style.overflow = '';
    }

    static getInstance(element) {
      const el = typeof element === 'string' ? document.querySelector(element) : element;
      return el ? new Modal(el) : null;
    }

    static getOrCreateInstance(element) {
      return new Modal(element);
    }
  }

  window.bootstrap.Modal = Modal;

  // Auto-bind data-bs-toggle="modal" and data-bs-dismiss="modal"
  document.addEventListener('click', function(e) {
    // Open modal
    const toggleBtn = e.target.closest('[data-bs-toggle="modal"]');
    if (toggleBtn) {
      e.preventDefault();
      const targetSelector = toggleBtn.getAttribute('data-bs-target') || toggleBtn.getAttribute('href');
      if (targetSelector) {
        const modal = new Modal(targetSelector);
        modal.show();
      }
      return;
    }

    // Dismiss modal
    const dismissBtn = e.target.closest('[data-bs-dismiss="modal"]');
    if (dismissBtn) {
      e.preventDefault();
      const modalEl = dismissBtn.closest('.modal');
      if (modalEl) {
        const modal = new Modal(modalEl);
        modal.hide();
      }
      return;
    }

    // Click on modal backdrop
    if (e.target.classList.contains('modal')) {
      const modal = new Modal(e.target);
      modal.hide();
    }
  });

  // ESC key closes active modals
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal.show').forEach(el => {
        new Modal(el).hide();
      });
    }
  });
})();
